const fmt=x=>Math.round(x).toLocaleString('en-US');
function stat(name,value){return '<label>'+name+'</label><strong>'+value+'</strong>';}
function section(name){return '<div class="sectiontitle">'+name+'</div>';}
function decision(action,name,desc,price){return '<button class="rowbtn" data-action="court-decision" data-type="'+action+'"><b>'+name+'</b> · '+price+'g <small>'+desc+'</small></button>';}
export function renderCourt(g,esc){
 const c=currentCourt(g),f=g.factions[g.player];if(!c)return '<p class="paragraph">Court records are unavailable.</p>';
 const event=currentRoyalEvent(g);
 let html='<div class="label">THE ROYAL HOUSE</div>'+
  '<div class="rule"><h3>'+esc(c.dynasty)+'</h3><div class="statlist">'+
  stat('Sovereign',characterLink(g.politics?.people?.[g.politics?.realms?.[g.player]?.ruler],esc,c.ruler.name))+stat('Ruler age',fmt(c.ruler.age))+
  stat('Designated heir',esc(c.heir.name))+stat('Heir age',fmt(c.heir.age))+
  stat('Stewardship',fmt(c.ruler.stewardship)+'/5')+stat('Martial ability',fmt(c.ruler.martial)+'/5')+
  stat('Diplomatic ability',fmt(c.ruler.diplomacy)+'/5')+stat('Successions',fmt(c.successions))+
  '</div></div>'+section('ROYAL ADVISORS')+
  '<div class="statlist">'+stat('Chief steward',fmt(c.steward)+'/5')+stat('Royal marshal',fmt(c.marshal)+'/5')+
  stat('Prestige',fmt(f.prestige))+stat('Legitimacy',fmt(f.legitimacy)+'%')+stat('Technology',fmt(f.tech)+'/10')+'</div>'+
  section('ISSUE A COURT DECISION')+
  decision('audience','Hold public audience','Restore stability and lower provincial unrest',120)+
  decision('steward','Promote chief steward','Permanently improve tax efficiency',250)+
  decision('marshal','Reform army command','Improve experience and morale of your armies',250)+
  decision('chronicle','Commission a chronicle','Gain prestige and legitimacy',180)+
  decision('succession','Secure the succession','Improve legitimacy and stability',220);
 if(event){
  html+=section('DECISION REQUIRED · ROYAL EVENT')+
   '<div class="rule"><div class="label">COURT DISPATCH</div><h3>'+esc(event.title)+'</h3>'+
   '<p class="paragraph">'+esc(event.description)+'</p>'+
   event.choices.map((ch,i)=>'<button class="rowbtn" data-action="royal-choice" data-choice="'+i+'">'+esc(ch.label)+
    '<small>'+Object.entries(ch).filter(([k])=>k!=='label').map(([k,v])=>esc(k)+' '+(v>0?'+':'')+fmt(v)).join(' · ')+'</small></button>').join('')+'</div>';
 }else html+=section('ROYAL DISPATCHES')+'<p class="paragraph">No unresolved court event. New events appear as the campaign advances.</p>';
 const threats=g.kingdom?.threats||[];
 if(threats.length)html+=section('FRONTIER WARNING')+threats.map(t=>
  '<div class="rule"><b>Enemy army gathering at '+esc(t.province)+'</b><p class="paragraph">'+fmt(t.eta)+' month(s) until invasion. Reinforce the garrison or recruit troops.</p></div>').join('');
 html+='<div class="smallnote">Ruler and heir names are fictional alternate-history content. Succession, decisions and events alter the simulated realm.</div>';
 return html+renderLivingCourt(g,esc)+renderPolitics(g,esc);
}
export function renderTrade(g,world,esc){
 const f=g.factions[g.player],pacts=Object.values(g.kingdom?.tradePacts||{}).filter(p=>p.partners.includes(g.player));
 let html='<div class="label">COMMERCE AND MERCHANTS</div>'+
  '<p class="paragraph">Merchant treaties increase monthly revenue. Markets improve their value. Improve relations through gifts, then negotiate from the Diplomacy tab.</p>'+
  '<div class="statlist">'+stat('Trade treaties',fmt(tradePactCount(g)))+stat('Revenue per month','+'+fmt(tradeIncome(g,g.player))+'g')+
   stat('Treasury',fmt(f.treasury)+'g')+'</div>'+section('TRADE PARTNERS');
 if(!pacts.length)html+='<p class="paragraph">No merchant treaties yet. Establish one with a court that has at least +10 relations.</p>';
 for(const treaty of pacts){
  const other=treaty.partners.find(id=>id!==g.player),name=g.factions[other]?.name||other;
  html+='<div class="rule"><div class="label">ACTIVE TREATY</div><h3>'+esc(name)+'</h3><div class="smallnote">Established on campaign turn '+fmt(treaty.founded)+'. Markets and relations support commerce.</div></div>';
 }
 html+=section('MERCHANT NETWORK')+'<p class="paragraph">The 1450 political map uses synthetic provinces, so these treaties are economy simulations—not verified medieval trade routes.</p>';
 return html;
}
export function renderLegacy(g,esc){
 const result=campaignStanding(g),goals=objectives(g);
 let html='<div class="label">THE LEGACY OF YOUR HOUSE</div>'+
  '<p class="paragraph">Your campaign is scored at the year 1500. Complete at least four of the six objectives while keeping your dynasty on the map to secure a victorious legacy.</p>'+
  '<div class="statlist">'+stat('Campaign year',fmt(g.year))+
  stat('Assessment year',fmt(result.targetYear))+
  stat('Legacy score',fmt(result.score))+stat('Completed objectives',fmt(result.fulfilled)+'/'+fmt(result.total))+
  '</div>'+section('DYNASTIC OBJECTIVES');
 for(const o of goals){
  const w=Math.round(o.progress*100);
  html+='<div class="rule"><div class="label">'+(o.complete?'✓ COMPLETE':'IN PROGRESS')+'</div>'+
   '<h3>'+esc(o.name)+'</h3><div class="smallnote">'+fmt(o.value)+' / '+fmt(o.target)+'</div>'+
   '<div class="unithealth"><div style="width:'+w+'%"></div></div></div>';
 }
 if(result.ended)html+=section('CAMPAIGN ASSESSMENT')+'<div class="rule"><h3>'+
  esc(result.outcome)+'</h3><p class="paragraph">Final score: '+fmt(result.score)+'</p></div>';
 else html+='<p class="paragraph">Your legacy continues. Advance months, build the economy, develop the court, and protect your borders.</p>';
 return html;
}

function renderPolitics(g,esc){
 const p=g.politics;if(!p)return '';const s=p.realms[g.player],r=p.people[s.ruler],vassals=Object.entries(p.holdings).filter(([id,v])=>v.realm===g.player&&g.provinces[id]?.owner===g.player&&v.lord!==r.id);
 const button=(action,id,label,extra='',input='')=>'<button class="rowbtn" data-action="politics" data-type="'+esc(action)+'" data-id="'+esc(id)+'" data-extra="'+esc(extra)+'" data-input="'+esc(input)+'">'+esc(label)+'</button>';
 const person=id=>p.people[id];const show=c=>c?characterLink(c,esc)+' · '+c.age+'y · '+esc(c.traits.join(', '))+(c.alive?'':' · deceased'):'None';const option=c=>c?esc(c.name)+' · '+c.age+'y · '+esc(c.traits.join(', ')):'None';
 let html=renderRegency(g,esc)+section('DYNASTY AND LIVING FAMILY')+'<div class="rule"><h3>'+esc(r.house)+'</h3><p class="paragraph">'+show(r)+'</p><div class="smallnote">Consort: '+show(person(r.spouse))+'</div><div class="smallnote">Parents: '+r.parents.map(id=>show(person(id))).join(' / ')+'</div>'+r.children.map(id=>'<div class="smallnote">Child: '+show(person(id))+' · spouse: '+show(person(person(id)?.spouse))+'</div>').join('')+'</div>';
 const dispatch=politicalDispatch(g);if(dispatch)html+=section('POLITICAL DISPATCH')+'<div class="rule"><h3>'+esc(dispatch.title)+'</h3><p class="paragraph">'+esc(dispatch.description)+'</p>'+dispatch.choices.map((x,i)=>button('dispatch',i,x.label+(x.cost?' ('+x.cost+'g)':''))).join('')+'</div>';
 html+=section('SUCCESSION LAW')+'<div class="rule"><b>'+esc(s.law)+'</b><p class="paragraph">Reform costs 250 gold, requires 65 legitimacy, and is limited to once per decade. House seniority gives the crown to the oldest eligible member of the house.</p>'+['eldest','youngest','elective','partition','seniority'].filter(l=>l!==s.law).map(l=>button('law',l,'Adopt '+l)).join('')+'</div>';
 html+=section('DYNASTIC MARRIAGES')+'<p class="paragraph">Eligible adults only. Weddings cost 180 gold; foreign matches also require +20 relations.</p>';
 const matches=marriageCandidates(g,g.player);if(matches.length){const groups=Object.groupBy?Object.groupBy(matches,x=>x.a):matches.reduce((a,x)=>((a[x.a]??=[]).push(x),a),{});for(const [id,opts] of Object.entries(groups)){const field='spouse-'+id;html+='<div class="rule"><b>'+show(person(id))+'</b><select class="select" id="'+esc(field)+'">'+opts.map(x=>'<option value="'+esc(x.b)+'">'+esc(x.label)+'</option>').join('')+'</select>'+button('marry',id,'Celebrate marriage (180g)','',field)+'</div>';}}else html+='<p class="paragraph">No eligible foreign matches at present.</p>';
 html+=section('ROYAL COUNCIL');const candidates=Object.values(p.people).filter(c=>c.alive&&c.realm===g.player&&c.age>=18&&c.id!==r.id&&!Object.values(s.council).includes(c.id)&&!Object.values(g.royalCourt?.realms[g.player]?.offices||{}).some(o=>o.person===c.id));
 for(const [role,id] of Object.entries(s.council)){const field='office-'+role;html+='<div class="rule"><b>'+esc(role)+'</b><div class="smallnote">'+show(person(id))+'</div>'+ (candidates.length?'<select class="select" id="'+field+'">'+candidates.map(c=>'<option value="'+esc(c.id)+'">'+option(c)+'</option>').join('')+'</select>'+button('appoint',role,'Appoint (80g)','',field):'')+'</div>';}
 html+=section('ROYAL HOUSEHOLD OFFICES')+'<details class="rule"><summary>Appoint salaried household specialists</summary><p class="paragraph">Offices are separate from council seats. Salaries are paid every three months; skill and opinion determine effectiveness.</p>';
 const offices=g.royalCourt?.realms[g.player]?.offices||{},mods=courtModifiers(g,g.player);
 html+='<div class="smallnote">Tax +'+Math.round((mods.tax-1)*100)+'% · Levies +'+Math.round((mods.levy-1)*100)+'% · Trade +'+Math.round((mods.trade-1)*100)+'%</div>';
 for(const [role,d] of Object.entries(COURT_OFFICES)){const o=offices[role],field='household-'+role,opts=courtCandidates(g,g.player,role);html+='<div class="rule"><b>'+esc(d.name)+'</b><p class="paragraph">'+esc(d.description)+' · '+d.salary+'g per quarter</p>'+(o?'<div class="smallnote">'+show(person(o.person))+'</div>'+button('court-dismiss',role,'Dismiss'):(opts.length?'<select class="select" id="'+field+'">'+opts.map(c=>'<option value="'+esc(c.id)+'">'+option(c)+' · '+esc(d.skill)+' '+c.skills[d.skill]+'</option>').join('')+'</select>'+button('court-appoint',role,'Appoint ('+(d.salary+40)+'g)','',''+field):'<div class="smallnote">No eligible unassigned adult.</div>'))+'</div>';}html+='</details>';
 html+=section('VASSAL CONTRACTS')+'<p class="paragraph">Tax yield '+Math.round(politicalRevenue(g,g.player)*100)+'% · recruitment yield '+Math.round(politicalLevy(g,g.player)*100)+'%. Raising obligations reduces loyalty.</p>';
 for(const [id,v] of vassals){html+='<div class="rule"><h3>'+esc(id.toUpperCase())+' · '+show(person(v.lord))+'</h3><div class="smallnote">Loyalty '+Math.round(v.loyalty)+'% · Wealth '+Math.round(v.wealth)+'g</div>';
 for(const kind of ['tax','levy','autonomy'])html+='<div class="smallnote">'+kind+': '+['Low','Standard','High'][v[kind]]+'</div>'+[0,1,2].filter(n=>n!==v[kind]).map(n=>button(kind,id,'Set '+kind+' '+['low','standard','high'][n],n)).join('');
 html+=button('gift',id,'Send gift (100g)')+button('replace',id,'Revoke and appoint (10 legitimacy)')+(v.loyalty<45?button('concede',id,'Negotiate concession (150g)'):'')+'</div>';}
 html+=section('POLITICAL SITUATIONS');const situations=Object.values(p.situations).filter(x=>x.realm===g.player);html+=situations.length?situations.map(x=>'<div class="rule"><b>'+esc(x.phase.toUpperCase())+' · '+esc(x.province)+'</b><p class="paragraph">'+show(person(x.lord))+' opposes royal authority. Negotiate or risk unrest.</p></div>').join(''):'<p class="paragraph">No active vassal grievances.</p>';
 return html;
}

export function renderConflict(g,world,esc){
 const c=initConflict(g),realm=g.player,p=g.politics,btn=(action,id,label,extra='',input='',disabled=false)=>'<button class="rowbtn"'+(disabled?' disabled':'')+' data-action="conflict" data-type="'+esc(action)+'" data-id="'+esc(id)+'" data-extra="'+esc(extra)+'" data-input="'+esc(input)+'">'+esc(label)+'</button>';
 const name=id=>g.factions[id]?.name||id,place=id=>world.provinces.find(x=>x.id===id)?.name||id;
 let html=section('COUNCIL AUTHORITY')+'<div class="rule"><b>'+esc(c.council[realm]||'advisory')+'</b><p class="paragraph">Binding councils can veto succession reform, title revocation and formal claim wars. Support varies by proposal.</p>'+btn('council','binding','Empower council (150g)')+btn('council','advisory','Return to advisory (150g)')+'</div>';
 for(const v of councilVotes(g,realm)){const person=p.people[v.id],war=councilVotes(g,realm,'war').find(x=>x.id===v.id),rev=councilVotes(g,realm,'revoke').find(x=>x.id===v.id);html+='<div class="rule"><b>'+characterLink(person,esc)+' · '+esc(v.role)+'</b><div class="smallnote">Law '+(v.yes?'YES':'NO')+' · War '+(war?.yes?'YES':'NO')+' · Revocation '+(rev?.yes?'YES':'NO')+'</div>'+ (v.favor?'<div class="smallnote">Favor pledged</div>':btn('favor',v.id,'Secure favor (80g)'))+'</div>';}
 html+=section('FACTIONS AND CIVIL WARS')+'<p class="paragraph">Highly autonomous, disloyal neighboring estates may demand independence. Concessions or a rebel victory can establish a new sovereign realm.</p>';
 const factions=Object.values(c.factions).filter(x=>x.realm===realm&&['organizing','ultimatum','civil war'].includes(x.status));
 if(!factions.length)html+='<p class="paragraph">No organized opposition. Vassals below 42 loyalty can form factions.</p>';
 for(const x of factions){html+='<div class="rule"><h3>'+esc(x.kind.toUpperCase())+' faction · '+esc(x.status)+(x.claimant?' · '+esc(p.people[x.claimant]?.name||x.claimant):'')+'</h3><p class="paragraph">'+x.members.map(id=>provinceLink(id,world,esc)).join(', ')+'</p><div class="smallnote">Pressure '+x.pressure+'% · Estimated rebel strength '+(x.rebels??x.power??0)+(Number.isFinite(x.strengthRatio)?' · '+x.strengthRatio+'% of nearby royal power':'')+(x.status==='ultimatum'?' · '+Math.max(0,x.deadline-g.turn)+' months to respond':'')+(x.status==='civil war'?' · War score '+x.score+' · Royal troops nearby '+fmt(civilWarForces(g,x,world).troops):'')+'</div>'+btn('accept',x.id,'Accept demands')+(x.status==='civil war'?(x.lastRound===g.turn?'<p class="smallnote">Campaign round completed this month.</p>':btn('mobilize',x.id,'Mobilize royal army (150g)'))+'<p class="smallnote">Only armies in rebel provinces or neighboring home provinces participate. Move troops nearby to strengthen the royal army.</p>':btn('negotiate',x.id,'Negotiate (150g)'))+(x.status==='ultimatum'?btn('refuse',x.id,'Reject ultimatum — civil war'):'')+'</div>';}
 html+=section('INTRIGUE AND CHANCERY');
 const running=Object.values(c.schemes).filter(x=>x.realm===realm&&x.status==='active');
 for(const x of running)html+='<div class="rule"><b>'+esc(x.kind)+' · '+esc(place(x.target))+'</b><div class="smallnote">'+Math.max(0,x.due-g.turn)+' months remaining · '+x.chance+'% estimated success</div></div>';
 const own=Object.values(g.provinces).filter(x=>x.owner===realm),foreign=Object.values(g.provinces).filter(x=>x.owner!==realm&&p.realms[x.owner]);
 for(const [type,label,targets] of [['fabricate','Fabricate claim (110g)',foreign],['undermine','Undermine foreign court (100g)',foreign],['sway','Sway vassal (60g)',own],['investigate','Investigate estate (80g)',own]]){const field='scheme-'+type;html+='<div class="rule"><b>'+esc(label)+'</b><select class="select" id="'+field+'">'+targets.map(v=>'<option value="'+esc(v.id)+'">'+esc(place(v.id))+' · '+esc(name(v.owner))+'</option>').join('')+'</select>'+btn('scheme',type,'Begin scheme','',field)+'</div>';}
 html+=renderIntrigue(g,esc);
 html+=section('TERRITORIAL CLAIMS');const claims=availableClaims(g,realm);const inherited=dynasticClaimOptions(g,world,realm).filter(x=>!x.existing);if(inherited.length)html+='<details class="rule"><summary>Inherited dynastic claims</summary>'+inherited.map(x=>'<div class="rule">'+characterLink(p.people[x.person],esc)+' · '+provinceLink(x.province,world,esc)+btn('dynastic-claim',x.person,'Recognize territorial claim (60g)',x.province)+'</div>').join('')+'</details>';
 if(!claims.length)html+='<p class="paragraph">No active claims. Use the chancellor to establish one.</p>';
 for(const x of claims)html+='<div class="rule"><b>'+provinceLink(x.province,world,esc)+'</b><div class="smallnote">Expires in '+Math.max(0,x.expires-g.turn)+' months · '+esc(name(g.provinces[x.province].owner))+'</div>'+btn('declare',x.province,'Declare claim war (5 prestige)')+'</div>';
 html+=section('WARS AND PEACE');const wars=Object.values(c.wars).filter(w=>w.status==='active'&&[w.attacker,w.defender].includes(realm));if(!wars.length)html+='<p class="paragraph">No formal claim wars.</p>';
 for(const w of wars){
  const terms=peaceTerms(g,w,realm);
  const occupied=Object.values(g.campaignWar.occupations).filter(o=>o.war===w.id);
  html+='<div class="rule"><b>'+esc(name(w.attacker))+' vs '+esc(name(w.defender))+'</b><div class="smallnote">Goal '+provinceLink(w.goal,world,esc)+' · Your war score '+(w.attacker===realm?w.score:-w.score)+' · Battles '+w.battles+'</div>';
  html+='<p class="paragraph">Occupied territories: '+(occupied.map(o=>provinceLink(o.province,world,esc)+' ('+esc(name(o.by))+')').join(', ')||'None')+'</p>';
  html+='<p class="smallnote">Signing peace starts a three-year truce.</p>';
  for(const term of terms)html+='<div>'+btn('peace',w.id,term.label,term.id,'',Boolean(term.reason))+'<p class="smallnote">'+esc(term.reason||term.description)+'</p></div>';
  html+='</div>';
 }
 html+=section('POLITICAL HISTORY')+c.history.filter(x=>x.realm===realm).slice(0,12).map(x=>'<div class="rule"><div class="smallnote">'+esc(x.message)+'</div></div>').join('');
 return html;
}

export function renderCivic(g,world,esc){
 const c=g.civic;if(!c)return '<p>Society records unavailable.</p>';const realm=g.player,s=c.realms[realm],gov=GOVERNMENTS[s.government],p=g.politics,r=p.people[p.realms[realm].ruler],rc=r.civic,mods=civicModifiers(g,realm),place=id=>world.provinces.find(x=>x.id===id)?.name||id;
 const button=(action,id,label,extra='',input='')=>'<button class="rowbtn" data-action="civic" data-type="'+esc(action)+'" data-id="'+esc(id)+'" data-extra="'+esc(extra)+'" data-input="'+esc(input)+'">'+esc(label)+'</button>';
 let html=section('GOVERNMENT AND INSTITUTIONS')+'<div class="rule"><h3>'+esc(gov.name)+'</h3><div class="smallnote">Authority '+Math.round(s.authority)+'% · Cohesion '+Math.round(s.cohesion)+'%</div><div class="smallnote">Tax '+Math.round(mods.tax*100)+'% · Levies '+Math.round(mods.levy*100)+'% · Trade '+Math.round(mods.trade*100)+'% · Construction cost '+Math.round(mods.build*100)+'%</div><p class="paragraph">'+esc(gov.desc)+'</p>'+button('government','',gov.action+' ('+gov.cost+'g)')+'</div>';
 if(s.government==='republic')html+='<p class="paragraph">Republican election in '+Math.max(0,60-g.turn+(s.lastElection??0))+' months. Elective succession is mandatory.</p>';
 html+=renderInstitutions(g,world,esc);
 html+=section('CULTURE AND FAITH')+'<div class="rule"><b>'+esc(s.culture)+'</b><p class="paragraph">'+esc(s.faith)+'</p><div class="smallnote">Patronage '+Math.round(s.patronage)+'% · Policy '+esc(s.policy)+'</div>'+['accommodation','pluralism','coercion'].filter(x=>x!==s.policy).map(x=>button('policy',x,'Adopt '+x+' (80g)')).join('')+button('patronage','','Support local institutions (110g)')+button('scholarship','','Fund scholarship (130g)')+'</div>';
 html+=section('PERSONAL LIFESTYLE')+'<div class="rule"><b>'+esc(r.name)+'</b><div class="smallnote">Focus '+esc(rc?.focus||'Unselected')+' · XP '+(rc?.xp||0)+' · Stress '+(rc?.stress||0)+'%</div><p class="paragraph">Perks: '+esc(rc?.perks.join(', ')||'None yet')+'</p>'+Object.entries(LIFESTYLES).filter(([id])=>id!==rc?.focus).map(([id,l])=>button('focus',id,'Study '+l.name)).join('')+button('rest','','Rest (70g)')+'</div>';
 html+=section('WARD EDUCATION');const guardians=Object.values(p.people).filter(x=>x.alive&&x.realm===realm&&x.age>=18);for(const id of r.children){const child=p.people[id];if(!child?.alive||child.age<6||child.age>=18)continue;const field='guardian-'+id;html+='<div class="rule"><b>'+esc(child.name)+' · age '+child.age+'</b><div class="smallnote">Guardian '+esc(p.people[child.civic?.guardian]?.name||'Unassigned')+' · Education progress '+(child.civic?.education||0)+'</div><select class="select" id="'+field+'">'+guardians.map(x=>'<option value="'+esc(x.id)+'">'+esc(x.name)+' · '+esc(Object.entries(x.skills).map(([k,v])=>k+': '+v).join(' · '))+'</option>').join('')+'</select>'+button('guardian',id,'Assign guardian','',field)+'</div>';}
 html+=section('PROVINCIAL COMMUNITIES');for(const v of Object.values(g.provinces).filter(x=>x.owner===realm)){const local=c.provinces[v.id];if(!local)continue;html+='<div class="rule"><b>'+esc(place(v.id))+'</b><p class="paragraph">'+esc(local.culture)+' · '+esc(local.faith)+'</p><div class="smallnote">Acceptance '+Math.round(local.acceptance)+'% · Local trust '+Math.round(local.localTrust)+'%</div>'+button('integrate',v.id,'Consult community (100g)')+'</div>';}
 html+=section('SOCIETY SITUATIONS');const crisis=c.situations['integration:'+realm];html+=crisis?'<div class="rule"><b>Regional integration '+esc(crisis.phase)+'</b><p class="paragraph">Average acceptance '+crisis.acceptance+'%. Improve local trust through consultation and accommodation.</p></div>':'<p class="paragraph">No regional integration crisis.</p>';
 const e=civicEvent(g);if(e)html+=section('SOCIETY DISPATCH')+'<div class="rule"><h3>'+esc(e.title)+'</h3><p class="paragraph">'+esc(e.description)+(e.province?' · '+esc(place(e.province)):'')+'</p>'+e.choices.map((x,i)=>button('event',i,x.label+(x.cost?' ('+x.cost+'g)':''))).join('')+'</div>';
 html+=section('SOCIETY CHRONICLE')+c.history.filter(x=>x.realm===realm).slice(0,10).map(x=>'<div class="rule"><div class="smallnote">'+esc(x.message)+'</div></div>').join('')+'<p class="paragraph">Starting identities and governments are simplified alternate-history design profiles, not verified demographic records.</p>';
 return html;
}

export function renderHeritage(g,world,esc){
 const a=g.heritage,realm=g.player,s=a.realms[realm],r=g.politics.people[g.politics.realms[realm].ruler],d=a.dynasties[realm+'|'+r.house]||{renown:0,legacies:[],achievements:[]},mods=heritageModifiers(g,realm),place=id=>world.provinces.find(p=>p.id===id)?.name||id;
 const button=(action,id,label,extra='',input='',guest='')=>'<button class="rowbtn" data-action="heritage" data-type="'+esc(action)+'" data-id="'+esc(id)+'" data-extra="'+esc(extra)+'" data-input="'+esc(input)+'" data-guest="'+esc(guest)+'">'+esc(label)+'</button>';
 let html=section('ROYAL ACTIVITIES AND JOURNEYS');const x=a.activities[realm];
 if(x){html+='<div class="rule"><h3>'+esc(ACTIVITIES[x.kind].name)+'</h3><p class="paragraph">'+esc(x.phase)+' · '+esc(place(x.path[x.index]))+' → '+esc(place(x.destination))+'</p><div class="smallnote">Quality '+Math.round(x.quality)+'% · '+(x.phase==='travel'?(x.path.length-1-x.index)+' travel steps remaining':x.remaining+' months remaining')+'</div><p class="paragraph">Route: '+x.path.map(id=>esc(place(id))).join(' → ')+'</p></div>';const e=activityIncident(g);if(e)html+='<div class="rule"><h3>'+esc(e.title)+'</h3><p class="paragraph">'+esc(e.desc)+'</p>'+e.choices.map((ch,i)=>button('incident',i,ch[0]+(ch[1]?' ('+ch[1]+'g)':''))).join('')+'</div>';}
 else{const dest=activityDestinations(g,world,realm),guests=world.factions.filter(f=>f.id!==realm&&Object.values(g.provinces).some(p=>p.owner===f.id)&&(g.factions[realm].relations[f.id]||0)>=-30);
 html+='<p class="paragraph">Travel takes one month per connected province. Events may delay the party or change the outcome.</p><select class="select" id="heritage-destination">'+dest.map(v=>'<option value="'+esc(v.id)+'">'+esc(place(v.id))+' · '+(v.route.length-1)+' travel months · '+(v.route.length-1)*15+'g travel cost</option>').join('')+'</select><p class="paragraph">Diplomatic summit guest</p><select class="select" id="heritage-guest">'+guests.map(f=>'<option value="'+esc(f.id)+'">'+esc(f.name)+'</option>').join('')+'</select>';
 for(const [id,rule] of Object.entries(ACTIVITIES)){const cd=Math.max(0,24-g.turn+(s.last[id]??-1000));html+='<div class="rule"><b>'+esc(rule.name)+'</b><div class="smallnote">'+rule.cost+'g + travel · '+rule.duration+' event months'+(cd?' · '+cd+' months cooldown':'')+'</div>'+button('activity',id,'Plan '+rule.name,'','heritage-destination',id==='summit'?'heritage-guest':'')+'</div>';}}
 html+=section('REGIONAL STRUGGLES');const struggles=struggleView(g,realm);if(!struggles.length)html+='<p class="paragraph">No predefined regional scenario for this polity.</p>';
 for(const v of struggles){const t=v.state;html+='<div class="rule"><h3>'+esc(v.name)+'</h3><p class="paragraph">'+esc(v.desc)+'</p><div class="smallnote">Phase '+esc(t.phase)+' · Tension '+t.tension+'% · Cooperation '+t.cooperation+'% · Cycle '+t.cycle+'</div><p class="paragraph">'+v.members.map(id=>esc(g.factions[id]?.name||id)+': '+(t.influence[id]||0)).join(' · ')+'</p>'+(t.ended===null?button('initiative',v.id,'Mediate (120g)','mediation')+button('initiative',v.id,'Apply diplomatic pressure (140g)','pressure')+button('initiative',v.id,'Commercial cooperation (150g)','commerce'):'<p class="paragraph">Scenario resolved; a new cycle can begin after five years.</p>')+'</div>';}
 html+=section('DYNASTIC HERITAGE')+'<div class="rule"><h3>'+esc(d.house||r.house)+'</h3><div class="smallnote">Renown '+d.renown+' · Tax '+Math.round(mods.tax*100)+'% · Levies '+Math.round(mods.levy*100)+'% · Trade '+Math.round(mods.trade*100)+'%</div><p class="paragraph">Achievements: '+esc(d.achievements.join(', ')||'None yet')+'</p>'+Object.entries(LEGACIES).map(([id,l])=>d.legacies.includes(id)?'<div class="smallnote">'+esc(l.name)+' · unlocked</div>':l.requires&&!d.legacies.includes(l.requires)?'<div class="smallnote">'+esc(l.name)+' · requires '+esc(LEGACIES[l.requires].name)+'</div>':button('legacy',id,l.name+' ('+l.cost+' renown)')).join('')+'</div>';
 html+=section('TREASURY AND ARTIFACTS');for(const [id,l] of Object.entries(RELICS))html+=button('artifact',id,'Commission '+l.name+' ('+l.cost+'g)');
 for(const item of Object.values(a.artifacts).filter(x=>x.realm===realm)){const l=RELICS[item.kind];html+='<div class="rule"><b>'+esc(l.name)+'</b><div class="smallnote">Created '+item.year+' · Condition '+item.durability+'% · '+(s.equipped[l.slot]===item.id?'Equipped':'Stored')+'</div>'+button('equip',item.id,'Equip')+button('repair',item.id,'Repair (80g)')+'</div>';}
 html+=section('DYNASTIC CHRONICLE')+a.history.filter(x=>x.realm===realm).slice(0,15).map(x=>'<div class="rule"><div class="smallnote">'+esc(x.message)+'</div></div>').join('');return html;
}

export function renderEconomy(g,world,esc){
 const e=g.economy,realm=g.player,s=e.realms[realm],f=g.factions[realm],land=Object.values(g.provinces).filter(p=>p.owner===realm),name=id=>world.provinces.find(p=>p.id===id)?.name||id,btn=(action,id,label,extra='',input='',third='')=>'<button class="rowbtn" data-action="economy" data-type="'+esc(action)+'" data-id="'+esc(id)+'" data-extra="'+esc(extra)+'" data-input="'+esc(input)+'" data-third="'+esc(third)+'">'+esc(label)+'</button>';
 let html=section('TREASURY AND CREDIT')+'<div class="rule"><div class="statlist">'+stat('Treasury',fmt(f.treasury)+'g')+stat('Inflation',fmt(s.inflation)+'%')+stat('Credit',fmt(s.credit)+'/100')+stat('Goods trade last month',(s.tradeNet>0?'+':'')+fmt(s.tradeNet)+'g')+'</div>'+[300,600,1200].map(n=>btn('loan',n,'Borrow '+n+'g')).join('')+btn('debase','','Debase currency (+250g)')+btn('stabilize','','Stabilize currency (180g)')+(!s.merchantGuild?btn('guild','','Charter merchant guild (250g)'):'<p class="paragraph">Merchant guild chartered.</p>')+'</div>';
 for(const l of Object.values(e.loans).filter(l=>l.realm===realm&&['active','defaulted'].includes(l.status)))html+='<div class="rule"><b>'+esc(l.status)+' loan · '+fmt(l.remaining+l.interest)+'g outstanding</b><div class="smallnote">Interest '+l.rate+'% monthly · '+Math.max(0,l.due-g.turn)+' months to maturity</div>'+btn('repay',l.id,l.status==='defaulted'?'Settle arrears':'Repay loan')+'</div>';
 html+=section('MARKET PRICES')+'<div class="statlist">'+Object.entries(GOODS).map(([id,v])=>stat(esc(v.name),fmt(e.prices[id])+'g')).join('')+'</div>';
 html+=section('TRADE ROUTES')+'<p class="paragraph">Domestic routes move stock between connected provinces. Foreign routes require a merchant treaty, transfer gold and goods, and close during formal wars. Last-month goods cash flow is separate from existing treaty income.</p>'+[0,1,2].map(n=>btn('tariff',n,'Set '+['free trade','standard','high tariff'][n])).join('');
 for(const r of Object.values(e.routes).filter(r=>r.realm===realm&&r.status==='active'))html+='<div class="rule"><b>'+esc(GOODS[r.good].name)+' · '+esc(name(r.from))+' → '+esc(name(r.to))+'</b><div class="smallnote">'+r.lastVolume+' units last month · '+r.lastValue+'g gross value · '+r.total+' units shipped</div>'+btn('close-route',r.id,'Close route')+'</div>';
 for(const p of land){const l=e.provinces[p.id],targets=tradeDestinations(g,world,realm,p.id),field='route-to-'+p.id,good='route-good-'+p.id;if(targets.length)html+='<details class="rule"><summary>Establish route from '+esc(name(p.id))+'</summary><select class="select" id="'+field+'">'+targets.map(x=>'<option value="'+esc(x.id)+'">'+esc(name(x.id))+' · '+esc(g.factions[x.owner]?.name||x.owner)+'</option>').join('')+'</select><select class="select" id="'+good+'">'+Object.entries(GOODS).map(([id,v])=>'<option value="'+esc(id)+'">'+esc(v.name)+'</option>').join('')+'</select>'+btn('route',p.id,'Establish route (90g)','',field,good)+'</details>';}
 html+=section('SETTLEMENTS AND INDUSTRIES');
 for(const p of land){const l=e.provinces[p.id];html+='<details class="rule"><summary><b>'+esc(name(p.id))+' · '+esc(SETTLEMENTS[l.tier])+'</b></summary><p class="paragraph">Resources: '+l.resources.map(id=>esc(GOODS[id].name)).join(', ')+'</p><div class="statlist">'+Object.entries(GOODS).map(([id,v])=>stat(esc(v.name),fmt(l.stock[id])+' · +'+fmt(l.output[id]||0))).join('')+'</div>'+btn('settlement',p.id,'Upgrade settlement ('+350*(l.tier+1)+'g)')+Object.entries(INDUSTRIES).map(([id,v])=>'<div class="smallnote">'+esc(v.name)+' · level '+l.industries[id]+' / 3 · '+esc(v.desc)+'</div>'+btn('industry',p.id,'Upgrade ('+industryCost(g,realm,p.id,id)+'g)',id)).join('')+'</details>';}
 html+=section('CRISES AND RELIEF');const active=Object.values(e.crises).filter(x=>g.provinces[x.province]?.owner===realm);html+=active.length?active.map(x=>'<div class="rule"><b>'+esc(CRISES[x.kind].name)+' · '+esc(name(x.province))+'</b><div class="smallnote">Severity '+fmt(x.severity)+'% · '+x.remaining+' months remaining</div>'+btn('relief',x.province,'Send relief (120g)')+'</div>').join(''):'<p class="paragraph">No active disasters in your holdings.</p>';
 html+=section('ECONOMIC CHRONICLE')+e.history.filter(x=>x.realm===realm).slice(0,12).map(x=>'<div class="rule"><div class="smallnote">'+esc(x.message)+'</div></div>').join('')+'<p class="paragraph">Resources and trade connections use the existing synthetic map and are gameplay approximations.</p>';return html;
}

export function renderArmyCommand(g,a,esc,prefix='army'){const r=g.military?.armies[a.id],ready=armyReadiness(g,a),field=prefix+'-commander-'+a.id,people=commanderCandidates(g,a.id),btn=(type,label,input='')=>'<button class="rowbtn" data-action="military" data-type="'+type+'" data-id="'+esc(a.id)+'" data-input="'+esc(input)+'">'+esc(label)+'</button>';if(!r)return '';return '<div class="army-command"><b>Commander: '+(r.commander&&g.politics.people[r.commander]?characterLink(g.politics.people[r.commander],esc):'Not appointed')+'</b><p class="smallnote">Martial skill improves combat power and morale. Only available adult court members are listed.</p><label for="'+esc(field)+'" class="smallnote">Choose commander</label><select class="select" id="'+esc(field)+'" '+(people.length?'':'disabled')+'>'+people.map(c=>'<option value="'+esc(c.id)+'" '+(c.id===r.commander?'selected':'')+'>'+esc(c.name)+' · Martial '+c.skills.martial+'</option>').join('')+'</select>'+(people.length?btn('commander','Appoint commander',field):'<p class="smallnote">No eligible commander available.</p>')+(r.commander?btn('dismiss-commander','Remove commander'):'')+'</div>';}
export function renderMilitary(g,world,esc){
 const realm=g.player,btn=(action,id,label,extra='')=>'<button class="rowbtn" data-action="military" data-type="'+esc(action)+'" data-id="'+esc(id)+'" data-extra="'+esc(extra)+'">'+esc(label)+'</button>';
 const armies=Object.values(g.armies).filter(a=>a.owner===realm),total=armies.reduce((n,a)=>n+a.infantry+a.archers+a.cavalry,0);
 let html=section('YOUR ARMIES')+'<p class="paragraph">'+fmt(total)+' troops across '+armies.length+' armies. Select an army to appoint a commander, resupply or train troops. Only troops stationed in the marching province join a land battle.</p>';
 if(!armies.length)html+='<p class="paragraph">No field armies. Recruit troops in one of your provinces.</p>';
 for(const a of armies.sort((a,b)=>(b.infantry+b.archers+b.cavalry)-(a.infantry+a.archers+a.cavalry))){const r=g.military.armies[a.id];if(!r)continue;const ready=armyReadiness(g,a),size=a.infantry+a.archers+a.cavalry;html+='<div class="rule army-overview"><h3>'+fmt(size)+' troops · '+esc(world.provinces.find(p=>p.id===a.province)?.name||a.province)+'</h3><div class="statlist">'+stat('Infantry',fmt(a.infantry))+stat('Archers',fmt(a.archers))+stat('Cavalry',fmt(a.cavalry))+stat('Supply',fmt(r.supply)+'%')+stat('Fatigue',fmt(r.fatigue)+'%')+stat('Combat power',fmt(ready.power*100)+'%')+'</div>'+(embarked(g,a.id)?'<p class="smallnote">At sea — command changes unavailable.</p>':renderArmyCommand(g,a,esc)+btn('resupply',a.id,'Resupply (65g + 8 grain)')+'<details><summary>Specialized regiments</summary>'+regimentOptions(g,realm).map(id=>'<div class="smallnote">'+esc(REGIMENTS[id].name)+' · '+(r.regiments[id]||0)+' trained</div>'+btn('specialize',a.id,'Train up to 30 ('+REGIMENTS[id].cost+'g)',id)).join('')+'</details>')+'</div>';}
 return html;
}
export function renderNaval(g,world,esc){
 const n=g.naval,realm=g.player,place=id=>world.provinces.find(p=>p.id===id)?.name||id,btn=(action,id,label,extra='',input='',third='')=>'<button class="rowbtn" data-action="naval" data-type="'+esc(action)+'" data-id="'+esc(id)+'" data-extra="'+esc(extra)+'" data-input="'+esc(input)+'" data-third="'+esc(third)+'">'+esc(label)+'</button>';
 let html=section('NAVAL COMMAND')+'<p class="paragraph">Sea routes connect abstract ports in the same sea basin. Atlas v4 travel time varies by distance; older maps retain three-month voyages. Fleet travel is strategic, not a real-time naval battle. Monthly upkeep: '+navalUpkeep(g,realm)+'g.</p>';
 for(const p of Object.values(n.ports).filter(x=>g.provinces[x.province]?.owner===realm)){const l=g.economy.provinces[p.province];html+='<div class="rule"><h3>'+esc(place(p.province))+' · Port level '+p.level+'</h3><div class="smallnote">'+esc(p.basins.join(', '))+(p.abstractHub?' · Regional sea hub':'')+' · Timber '+Math.floor(l.stock.timber)+' · Tools '+Math.floor(l.stock.tools)+(portBlocked(g,p.province)?' · BLOCKADED':'')+(controller(g,p.province)!==realm?' · OCCUPIED':'')+'</div>'+btn('port',p.province,'Upgrade port ('+300*p.level+'g)')+Object.entries(SHIPS).map(([id,d])=>btn('ship',p.province,d.name+' ('+d.cost+'g / '+d.timber+' timber / '+d.tools+' tools)',id)).join('')+'</div>';}
 html+=section('FLEETS');
 for(const f of Object.values(n.fleets).filter(x=>x.realm===realm)){const s=fleetStats(f),dest=fleetDestinations(g,f),targets=blockadeTargets(g,f),d='fleet-dest-'+f.id,a='fleet-army-'+f.id,b='fleet-target-'+f.id;html+='<div class="rule"><h3>'+esc(f.id)+' · '+esc(place(f.port))+'</h3><div class="smallnote">'+esc(f.status)+' · '+(f.target?esc(place(f.target))+' · ':'')+f.remaining+' months remaining</div><div class="statlist">'+stat('Ships',s.count)+stat('Capacity',s.capacity)+stat('Combat strength',s.power)+stat('Monthly upkeep',s.upkeep+'g')+'</div><p class="paragraph">'+Object.entries(f.ships).map(([id,v])=>esc(SHIPS[id].name)+': '+v).join(' · ')+'</p>';
 if(f.status==='docked'){if(dest.length)html+='<select class="select" id="'+d+'">'+dest.map(x=>'<option value="'+esc(x.province)+'">'+esc(place(x.province))+' · '+voyageMonths(g,f.port,x.province)+' mo.</option>').join('')+'</select><select class="select" id="'+a+'"><option value="">Fleet only</option>'+Object.values(g.armies).filter(x=>x.owner===realm&&x.province===f.port&&!embarked(g,x.id)).map(x=>'<option value="'+esc(x.id)+'">'+esc(x.commander)+' · '+(x.infantry+x.archers+x.cavalry)+' troops</option>').join('')+'</select>'+btn('voyage',f.id,'Begin voyage','',d,a);
 if(targets.length)html+='<select class="select" id="'+b+'">'+targets.map(x=>'<option value="'+esc(x.province)+'">'+esc(place(x.province))+'</option>').join('')+'</select>'+btn('blockade',f.id,'Sail to blockade','',b);if(portBlocked(g,f.port))html+=btn('break-blockade',f.id,'Sortie to break blockade');}
 else if(['blockade','approach'].includes(f.status))html+=btn('recall',f.id,'Recall fleet');html+='</div>';}
 html+=section('NAVAL CHRONICLE')+n.history.filter(x=>x.realm===realm).slice(0,12).map(x=>'<div class="rule"><div class="smallnote">'+esc(x.message)+'</div></div>').join('');return html;
}

export function renderStrategy(g,world,esc){
 const realm=g.player,s=g.strategy,name=id=>g.factions[id]?.name||id,others=world.factions.filter(f=>f.id!==realm&&Object.values(g.provinces).some(p=>p.owner===f.id));
 const btn=(action,id,label,input='',second='')=>'<button class="rowbtn" data-action="strategy" data-type="'+esc(action)+'" data-id="'+esc(id)+'" data-input="'+esc(input)+'" data-second="'+esc(second)+'">'+esc(label)+'</button>';
 let html=section('STRATEGIC INTELLIGENCE')+'<p class="paragraph">Estimates reflect current forces, ruler temperament, relations and formal wars. Plans are reviewed every six months and change on succession.</p>';
 const ranked=borderRealms(g,world,realm).map(id=>({id,risk:threatAssessment(g,world,realm,id)})).sort((a,b)=>b.risk-a.risk);
 for(const {id,risk} of ranked){const t=temperament(g,id),p=strategicPlan(g,id);html+='<div class="rule"><h3>'+esc(name(id))+'</h3><div class="smallnote">'+esc(t.name)+' · Threat '+risk+'/100 · Field strength '+Math.round(militaryStrength(g,id))+'</div><p class="paragraph">Estimated objective: '+esc(p?.goal||'unassessed')+(p?.target?' · '+esc(name(p.target)):'')+'</p><div class="smallnote">Aggression '+t.aggression+' · Prudence '+t.prudence+' · Commerce '+t.commerce+' · Diplomacy '+t.diplomacy+'</div></div>';}
 html+=section('DEFENSIVE PACTS')+'<p class="paragraph">Five-year agreements against a named threat. Partners contribute abstract defensive reserve strength, not separate controllable armies.</p><select class="select" id="pact-partner">'+others.map(f=>'<option value="'+esc(f.id)+'">'+esc(f.name)+'</option>').join('')+'</select><select class="select" id="pact-target">'+others.map(f=>'<option value="'+esc(f.id)+'">'+esc(f.name)+'</option>').join('')+'</select>'+btn('pact','','Propose defensive pact (100g)','pact-partner','pact-target');
 for(const p of Object.values(s.pacts).filter(p=>p.members.includes(realm)&&p.expires>g.turn))html+='<div class="rule"><b>'+esc(p.members.filter(id=>id!==realm).map(name).join(', '))+' · Against '+esc(name(p.target))+'</b><div class="smallnote">'+Math.max(0,p.expires-g.turn)+' months remaining · Combined reserve support '+defenseSupport(g,realm,p.target)+'</div>'+btn('leave',p.id,'Dissolve pact')+'</div>';
 html+=section('FOREIGN RULERS');for(const f of others){const p=strategicPlan(g,f.id),t=temperament(g,f.id);html+='<details class="rule"><summary>'+esc(f.name)+' · '+esc(t.name)+'</summary><p class="paragraph">Objective: '+esc(p?.goal||'unassessed')+(p?.target?' · '+esc(name(p.target)):'')+'</p><div class="smallnote">Aggression '+t.aggression+' · Prudence '+t.prudence+' · Commerce '+t.commerce+' · Diplomacy '+t.diplomacy+'</div></details>';}
 return html;
}

export function renderStories(g,world,esc){
 const realm=g.player,s=g.chronicles.realms[realm],r=g.politics.people[g.politics.realms[realm].ruler],d=regionalDecision(g,realm);
 const btn=(action,id,label,input='')=>'<button class="rowbtn" data-action="story" data-type="'+esc(action)+'" data-id="'+esc(id)+'" data-input="'+esc(input)+'">'+esc(label)+'</button>';
 let html=section('REGIONAL DECISION')+'<div class="rule"><h3>'+esc(d[0])+'</h3><p class="paragraph">'+esc(d[1])+'</p><div class="smallnote">180g · '+Math.max(0,36-g.turn+s.decisionAt)+' months cooldown remaining</div>'+btn('decision','','Enact decision')+'</div>';
 html+=section('PERSONAL AMBITIONS');
 if(s.ambition){const a=AMBITIONS[s.ambition.id];html+='<div class="rule"><h3>'+esc(a.name)+'</h3><p class="paragraph">'+esc(a.desc)+'</p><div class="smallnote">Reward: '+a.reward+' prestige and dynastic renown, 6 legitimacy.</div>'+btn('abandon','','Abandon ambition (-5 prestige)')+'</div>';}else for(const [id,a] of Object.entries(AMBITIONS)){if(s.completed.some(x=>x.ambition===id&&x.ruler===r.id)||id==='resilience'&&(r.civic?.stress||0)<35)continue;html+='<div class="rule"><b>'+esc(a.name)+'</b><p class="paragraph">'+esc(a.desc)+'</p>'+btn('ambition',id,'Choose ambition')+'</div>';}
 html+=section('FRIENDS AND RIVALS');const people=Object.values(g.politics.people).filter(p=>p.alive&&p.realm===realm&&p.age>=18&&p.id!==r.id);
 html+='<p class="paragraph">Personal opinions influence council votes and provincial lord loyalty.</p><select class="select" id="story-person">'+people.map(p=>'<option value="'+esc(p.id)+'">'+esc(p.name)+' · opinion '+personalOpinion(g,r.id,p.id)+'</option>').join('')+'</select>'+btn('befriend','','Offer friendship (90g)','story-person')+btn('challenge','','Challenge courtier','story-person');
 for(const x of relationshipList(g,realm).filter(x=>g.politics.people[x.other]?.alive).sort((a,b)=>b.opinion-a.opinion))html+='<div class="rule"><b>'+esc(g.politics.people[x.other].name)+'</b><div class="smallnote">'+esc(x.kind)+' · Opinion '+x.opinion+'</div></div>';
 html+=section('ONGOING STORIES');const x=currentChain(g);if(x){html+='<div class="rule"><h3>'+esc(x.name)+' · '+(x.stage+1)+'/'+x.stageCount+'</h3><b>'+esc(x.title)+'</b><p class="paragraph">'+esc(x.desc)+'</p>'+(x.target&&g.politics.people[x.target]?'<p class="paragraph">Courtier: '+esc(g.politics.people[x.target].name)+'</p>':'')+(g.turn>=x.due?x.choices.map((ch,i)=>btn('chain',i,ch[0]+(ch[1]?' ('+ch[1]+'g)':''))).join(''):'<div class="smallnote">Next stage in '+(x.due-g.turn)+' months</div>')+'</div>';}else html+='<p class="paragraph">No active storyline. Succession, noble discontent, disasters, trade and rivalries may trigger new stories.</p>';
 html+=renderExpanded(g,world,esc);
 html+=section('COURT CHRONICLE')+g.chronicles.history.filter(x=>x.realm===realm).slice(0,20).map(x=>'<div class="rule"><div class="smallnote">'+esc(x.message)+'</div></div>').join('');return html;
}

export function renderFeudal(g,world,esc){
 const realm=g.player,r=g.politics.realms[realm].ruler,titles=titleList(g,realm),name=id=>g.politics.people[id]?.name||id,place=id=>world.provinces.find(p=>p.id===id)?.name||id;
 const btn=(action,id,label,input='')=>'<button class="rowbtn" data-action="feudal" data-type="'+esc(action)+'" data-id="'+esc(id)+'" data-input="'+esc(input)+'">'+esc(label)+'</button>';
 const adults=Object.values(g.politics.people).filter(p=>p.alive&&p.realm===realm&&p.age>=18&&!isImprisoned(g,p.id)&&p.id!==r);
 const crown=titles.filter(t=>t.tier==='province'&&t.holder===r);
 let html=section('TITLE HIERARCHY')+'<div class="rule"><h3>'+esc(g.factions[realm].name)+'</h3><p class="paragraph">Sovereign: '+esc(name(r))+' · '+crown.length+' personally held provinces. Crown → regional titles → provincial titles. Districts use the prototype map; they are not historical duchy boundaries.</p></div>';
 for(const t of titles.filter(t=>t.tier==='regional')){const field='regional-'+t.id.replaceAll(':','-'),lords=adults.filter(p=>t.members.some(id=>g.politics.holdings[id].lord===p.id));html+='<details class="rule"><summary>'+esc(t.name)+' · '+esc(name(t.holder))+'</summary><p class="paragraph">Regional loyalty effect: '+regionalLoyalty(g,t.members[0]).toFixed(1)+'</p>'+(lords.length?'<select class="select" id="'+field+'">'+lords.map(p=>'<option value="'+esc(p.id)+'">'+esc(p.name)+'</option>').join('')+'</select>'+btn('regional',t.id,'Grant regional title (120g)',field):'');
 for(const id of t.members){const v=g.politics.holdings[id],p=titles.find(x=>x.province===id),grant='grant-'+id;html+='<div class="rule"><b>'+provinceLink(id,world,esc)+' · '+characterLink(g.politics.people[v.lord],esc)+'</b><div class="smallnote">Loyalty '+Math.round(v.loyalty)+'%'+(isImprisoned(g,v.lord)?' · imprisoned':'')+'</div>';
 if(v.lord===r&&adults.length)html+='<select class="select" id="'+grant+'">'+adults.map(a=>'<option value="'+esc(a.id)+'">'+esc(a.name)+'</option>').join('')+'</select>'+btn('grant',p.id,'Grant province',grant);
 else if(v.lord!==r){html+=btn('reclaim',p.id,'Reclaim with evidence (8 legitimacy)');if(!isImprisoned(g,v.lord))html+=btn('arrest',v.lord,'Arrest with evidence (3 legitimacy)');}html+='</div>';}html+='</details>';}
 html+=section('CROWN CLAIMANTS')+'<p class="paragraph">Other eligible children inherit claims on succession. Discontented vassals may support an adult claimant when legitimacy is low.</p>';for(const c of claimantCandidates(g,realm))html+='<div class="rule"><b>'+esc(name(c.person))+'</b><div class="smallnote">Claim from '+esc(name(c.from))+' · expires in '+Math.max(0,180-g.turn+c.created)+' months</div></div>';
 html+=section('PRISONERS AND RANSOM');for(const x of Object.values(g.feudal.prisoners).filter(x=>x.status==='held'&&(x.captor===realm||x.realm===realm)))html+='<div class="rule"><b>'+esc(name(x.person))+'</b><div class="smallnote">'+esc(x.reason)+' · held by '+esc(g.factions[x.captor]?.name||x.captor)+' · '+(g.turn-x.started)+' months</div>'+(x.captor===realm?btn('release',x.person,'Release prisoner')+btn('ransom',x.person,'Ransom (100g)'):'')+'</div>';
 return html;
}

export function renderIdentity(g,world,esc){
 const realm=g.player,s=g.identity.realms[realm],c=g.civic.realms[realm],place=id=>world.provinces.find(p=>p.id===id)?.name||id;
 const btn=(action,id,label,extra='',input='')=>'<button class="rowbtn" data-action="identity" data-type="'+esc(action)+'" data-id="'+esc(id)+'" data-extra="'+esc(extra)+'" data-input="'+esc(input)+'">'+esc(label)+'</button>';
 const mod=identityModifiers(g,realm);let html=section('FAITH AND LOCAL INSTITUTIONS')+'<div class="rule"><h3>'+esc(c.faith)+'</h3><p class="paragraph">Court culture: '+esc(c.culture)+' · Institutional backing '+Math.round(s.faithAuthority)+'/100</p><p class="paragraph">Institutions support existing local communities. Dialogue projects require trust and non-coercive policy. Local identities are simplified gameplay abstractions.</p></div>';
 const faiths=localIdentities(g,realm).faith.filter(id=>id!==c.faith);if(faiths.length)html+='<select class="select" id="identity-faith">'+faiths.map(id=>'<option value="'+esc(id)+'">'+esc(id)+'</option>').join('')+'</select>'+btn('adopt-faith','','Adopt a local faith (250g)','','identity-faith');
 for(const p of Object.values(g.provinces).filter(p=>p.owner===realm)){const l=g.civic.provinces[p.id],inst=g.identity.institutions[p.id],x=g.identity.projects[p.id];html+='<details class="rule"><summary>'+esc(place(p.id))+' · '+esc(l.faith)+'</summary><div class="smallnote">'+esc(l.culture)+' · Acceptance '+Math.round(l.acceptance)+' · Trust '+Math.round(l.localTrust)+' · Institution '+inst.level+'/3</div>'+btn('institution',p.id,'Expand local institution ('+180*(inst.level+1)+'g)')+btn('consult',p.id,'Consult community (100g)');
 if(x)html+='<p class="paragraph">'+esc(x.kind)+' dialogue · '+Math.round(x.progress)+'%</p>'+btn('cancel',p.id,'End dialogue');else{if(l.faith!==c.faith)html+=btn('dialogue',p.id,'Begin voluntary faith dialogue (180g)','faith');if(l.culture!==c.culture)html+=btn('dialogue',p.id,'Begin voluntary cultural dialogue (180g)','culture');}html+='</details>';}
 html+=renderCommunityCouncil(g,esc);
 html+=section('CULTURAL TRADITIONS')+'<p class="paragraph">'+s.traditions.length+'/4 slots · tax '+Math.round(mod.tax*100)+'% · levy '+Math.round(mod.levy*100)+'% · trade '+Math.round(mod.trade*100)+'% · construction '+Math.round(mod.build*100)+'%</p>';
 for(const [id,d] of Object.entries(TRADITIONS))html+='<div class="rule"><b>'+esc(d.name)+(s.traditions.includes(id)?' · adopted':'')+'</b><p class="paragraph">'+esc(d.desc)+'</p>'+(s.traditions.includes(id)?'':btn('tradition',id,'Adopt (350g, 20 prestige)'))+'</div>';
 html+=section('INNOVATION TREE');const available=researchOptions(g,realm);if(s.research)html+='<div class="rule"><b>Researching '+esc(INNOVATIONS[s.research.id].name)+'</b><p class="paragraph">'+Math.round(s.research.progress)+' / '+INNOVATIONS[s.research.id].cost+' research points</p></div>';
 for(const [id,d] of Object.entries(INNOVATIONS))html+='<div class="rule"><b>'+esc(d.name)+' · '+(s.innovations.includes(id)?'Discovered':available.includes(id)?'Available':'Locked')+'</b><p class="paragraph">'+esc(d.desc)+'</p>'+(d.requires.length?'<div class="smallnote">Requires '+d.requires.map(k=>esc(INNOVATIONS[k].name)).join(', ')+'</div>':'')+(!s.research&&available.includes(id)?btn('research',id,'Commission (150g)'):'')+'</div>';
 return html;
}

export function renderIntrigue(g,esc){
 const realm=g.player,s=g.intrigue,name=id=>g.politics.people[id]?.name||id;
 if(!s)return '';
 const btn=(type,id,label,input='')=>'<button class="rowbtn" data-action="intrigue" data-type="'+esc(type)+'" data-id="'+esc(id)+'" data-input="'+esc(input)+'">'+esc(label)+'</button>';
 const options=people=>people.map(p=>'<option value="'+esc(p.id)+'">'+esc(p.name)+' · '+esc(g.factions[p.realm]?.name||p.realm)+'</option>').join('');
 let html=section('CHARACTER INTRIGUE')+'<details class="rule"><summary>Plots, secrets and counterespionage</summary><p class="paragraph">Run one character plot at a time. Agents increase success but may expose the conspiracy.</p>';
 const active=activePlots(g,realm);
 for(const p of active){const odds=plotOdds(g,p),field='agent-'+p.id,agents=agentOptions(g,p);html+='<div class="rule"><b>'+esc(PLOTS[p.kind].name)+' · '+esc(name(p.target))+'</b><div class="smallnote">'+Math.max(0,p.due-g.turn)+' months · '+odds.chance+'% success · '+odds.exposure+'% exposure · '+p.agents.length+'/3 agents</div>'+ (agents.length&&p.agents.length<3?'<select class="select" id="'+field+'">'+options(agents)+'</select>'+btn('agent',p.id,'Recruit agent (60g)',field):'')+btn('cancel',p.id,'Abandon plot')+'</div>';}
 if(!active.length)for(const [id,d] of Object.entries(PLOTS)){const field='plot-'+id,targets=plotTargets(g,realm,id);if(targets.length)html+='<div class="rule"><b>'+esc(d.name)+'</b><div class="smallnote">'+d.cost+'g · '+d.months+' months</div><select class="select" id="'+field+'">'+options(targets)+'</select>'+btn('start',id,'Begin plot',field)+'</div>';}
 html+='<div class="rule"><b>Counterespionage</b><p class="paragraph">'+Math.max(0,(s.security[realm]?.until||0)-g.turn)+' months remaining.</p>'+btn('security','','Strengthen security (120g)')+'</div>';
 for(const x of knownSecrets(g,realm)){const strength=hookStrength(g,realm,x.person);html+='<div class="rule"><b>'+esc(name(x.person))+' · '+esc(SECRETS[x.kind].name)+'</b>'+btn('expose',x.id,'Expose secret')+(strength?'<div class="smallnote">Political leverage '+strength+'/3</div>':x.usedBy?.includes(realm)?'<div class="smallnote">Leverage already used</div>':btn('blackmail',x.id,'Obtain leverage'))+(strength&&Object.values(g.politics.holdings).some(v=>v.realm===realm&&v.lord===x.person)?btn('favor',x.person,'Spend leverage for loyalty'):'')+'</div>';}
 html+='<div class="sectiontitle">INTELLIGENCE HISTORY</div>'+s.history.filter(x=>x.realm===realm).slice(0,8).map(x=>'<div class="smallnote">'+esc(x.message)+'</div>').join('')+'</details>';return html;
}

export function renderInstitutions(g,world,esc){
 const realm=g.player,s=institutionState(g,realm),d=INSTITUTION_TYPES[g.civic.realms[realm].government];if(!s||!d)return '';
 const place=id=>world.provinces.find(p=>p.id===id)?.name||id,name=id=>g.politics.people[id]?.name||id,targets=institutionTargets(g,realm),mod=institutionModifiers(g,realm);
 const btn='<button class="rowbtn" data-action="institution" data-input="'+(targets.length?'institution-target':'')+'" data-second="'+(s.mode==='administration'?'institution-person':'')+'">'+esc(d.action)+' ('+d.cost+'g)</button>';
 let html='<details class="rule"><summary>'+esc(d.name)+'</summary><div class="smallnote">Next institutional action in '+Math.max(0,s.last+6-g.turn)+' months · Tax '+Math.round(mod.tax*100)+'% · Levies '+Math.round(mod.levy*100)+'% · Trade '+Math.round(mod.trade*100)+'%</div>';
 const descriptions={estates:'Negotiate three-year estate compacts to improve local loyalty and levy support.',administration:'Assign qualified administrators to provinces. Stewardship affects tax yield.',merchants:'Invest in landed merchant houses. Their private wealth and trade influence grow over time.',retainers:'Fund retainer households to raise morale, levy capacity and their loyalty.',herds:'Maintain herds that provide food and levy capacity, but decline during shortages.',reserves:'Set aside communal food reserves for future shortages.',tribute:'Negotiate three-year monthly tribute payments with willing foreign realms.'};
 html+='<p class="paragraph">'+esc(descriptions[s.mode])+'</p>';
 if(targets.length)html+='<select class="select" id="institution-target">'+targets.map(id=>'<option value="'+esc(id)+'">'+esc(s.mode==='tribute'?g.factions[id].name:['estates','administration'].includes(s.mode)?place(id):name(id))+'</option>').join('')+'</select>';
 if(s.mode==='administration')html+='<select class="select" id="institution-person">'+Object.values(g.politics.people).filter(p=>p.alive&&p.realm===realm&&p.age>=18&&p.skills.stewardship>=2&&!isImprisoned(g,p.id)&&p.id!==g.politics.realms[realm].ruler).map(p=>'<option value="'+esc(p.id)+'">'+esc(p.name)+' · stewardship '+p.skills.stewardship+'</option>').join('')+'</select>';
 if(targets.length||['herds','reserves'].includes(s.mode))html+=btn;
 if(s.mode==='herds'||s.mode==='reserves')html+='<div class="smallnote">'+(s.mode==='herds'?'Herds: '+s.herds+'/100':'Reserve food: '+s.reserves+'/120')+'</div>';
 for(const [id,x] of Object.entries(s.compacts))html+='<div class="smallnote">'+esc(place(id))+' · compact '+Math.max(0,x.until-g.turn)+' months</div>';
 for(const [id,x] of Object.entries(s.offices))html+='<div class="smallnote">'+esc(place(id))+' · '+esc(name(x.person))+'</div>';
 for(const x of [...Object.values(s.houses),...Object.values(s.retainers)])html+='<div class="smallnote">'+esc(name(x.person))+' · level '+x.level+'/3</div>';
 for(const [id,x] of Object.entries(s.tributes))html+='<div class="smallnote">'+esc(g.factions[id]?.name||id)+' · '+x.amount+'g/month · '+Math.max(0,x.until-g.turn)+' months</div>';
 return html+'</details>';
}

export function renderDiplomaticAgreements(g,other,esc){
 const d=g.diplomacy,r=g.player;if(!d)return '';const name=id=>g.factions[id]?.name||id;
 const btn=(type,id,label,input='')=>'<button class="rowbtn" data-action="diplomatic-agreement" data-type="'+esc(type)+'" data-id="'+esc(id)+'" data-input="'+esc(input)+'">'+esc(label)+'</button>';
 let html='<details class="rule"><summary>Treaties and allied support</summary>';const links=activeMarriageLinks(g,r,other);if(links.length)html+='<p class="smallnote">Living dynastic ties: '+links.map(x=>characterLink(g.politics.people[x.a],esc)+' × '+characterLink(g.politics.people[x.b],esc)).join(', ')+'</p>';
 html+=nonAggression(g,r,other)?'<p class="paragraph">Non-aggression agreement active.</p>'+btn('break',other,'Repudiate agreement (prestige and legitimacy penalty)'):btn('pact',other,'Non-aggression agreement (80g)');
 html+=btn('guarantee',other,'Guarantee independence (100g)');
 for(const p of Object.values(d.guarantees).filter(x=>x.protected===r||x.guarantor===r))html+='<div class="smallnote">'+esc(name(p.guarantor))+' guarantees '+esc(name(p.protected))+' · '+Math.max(0,p.until-g.turn)+' months</div>';
 for(const w of Object.values(g.conflict.wars).filter(w=>w.status==='active'&&[w.attacker,w.defender].includes(r))){const enemy=w.attacker===r?w.defender:w.attacker,ids=aidOptions(g,r,w),field='aid-'+w.id;html+='<div class="rule"><b>War with '+esc(name(enemy))+'</b><div class="smallnote">Allied logistical support '+aidStrength(g,r,enemy)+' · abstract campaign strength, not allied field units.</div>';if(ids.length)html+='<select class="select" id="'+field+'">'+ids.map(id=>'<option value="'+esc(id)+'">'+esc(name(id))+'</option>').join('')+'</select>'+btn('aid',w.id,'Request allied aid',field);html+='</div>';}
 return html+'</details>';
}

function livingButton(type,id,label,input='',esc=String){return '<button class="rowbtn" data-action="living" data-type="'+esc(type)+'" data-id="'+esc(id)+'" data-input="'+esc(input)+'">'+esc(label)+'</button>';}
function livingOffice(g,role,label,esc){const s=g.living.realms[g.player],field='living-'+role,options=officeOptions(g,g.player,role);return '<div class="rule"><b>'+esc(label)+'</b><p class="paragraph">'+esc(g.politics.people[s[role]]?.name||'Unappointed')+'</p>'+(options.length?'<select class="select" id="'+field+'">'+options.map(p=>'<option value="'+esc(p.id)+'">'+esc(p.name)+' · learning '+p.skills.learning+'</option>').join('')+'</select>'+livingButton('appoint',role,'Appoint (100g)',field,esc):'')+'</div>';}
export function renderLivingCourt(g,esc){if(!g.living)return '';const r=g.player,s=g.living.realms[r],head=g.politics.people[g.politics.realms[r].ruler];if(!s)return '';const h=characterHealth(g,head.id);let html='<details class="rule"><summary>Family health and court physician</summary><p class="paragraph">Sovereign: '+esc(h.condition)+' · severity '+h.severity+'/100</p>'+livingOffice(g,'physician','Court physician',esc);for(const p of Object.values(g.politics.people).filter(p=>p.alive&&p.realm===r&&characterHealth(g,p.id).severity>0)){const h=characterHealth(g,p.id);html+='<div class="rule"><b>'+esc(p.name)+'</b><div class="smallnote">'+esc(h.condition)+' · severity '+h.severity+'/100</div>'+livingButton('care',p.id,'Provide care (70g)','',esc)+'</div>';}html+='</details><details class="rule"><summary>Cadet houses</summary><p class="paragraph">Landed adult relatives may establish a hereditary branch while retaining dynastic succession rights.</p>';for(const id of [...new Set(Object.values(g.politics.holdings).filter(h=>h.realm===r).map(h=>h.lord))]){const p=g.politics.people[id];if(p?.alive&&p.age>=18&&p.house===head.house&&id!==head.id&&!p.cadetBranch)html+=livingButton('branch',id,'Charter '+p.name+' (200g, 20 prestige)','',esc);}for(const x of Object.values(g.living.branches).filter(x=>x.realm===r))html+='<div class="smallnote">'+esc(x.name)+' · '+Object.values(g.politics.people).filter(p=>p.alive&&p.cadetBranch===x.founder).length+' living members</div>';return html+'</details>';}
export function renderCommunityCouncil(g,esc){if(!g.living?.realms[g.player])return '';const s=g.living.realms[g.player];let html='<details class="rule"><summary>Community leadership</summary>'+livingOffice(g,'faithAdvisor','Religious institutions advisor',esc)+livingOffice(g,'culturePatron','Cultural patron',esc)+'<p class="paragraph">Research bonus: '+researchPatronBonus(g,g.player)+' points per quarter. Institutional priority: '+esc(COMMUNITY_POLICIES[s.policy].name)+'</p>';for(const [id,d] of Object.entries(COMMUNITY_POLICIES))if(id!==s.policy)html+='<p class="smallnote">'+esc(d.desc)+'</p>'+livingButton('policy',id,'Adopt '+d.name+' (150g)','',esc);return html+'</details>';}

export function renderExpanded(g,world,esc){
 if(!g.expanded?.realms[g.player])return '';
 const r=g.player,place=id=>world.provinces.find(p=>p.id===id)?.name||id;
 const target=t=>t.faction?(g.conflict.factions[t.faction]?.kind||'Local')+' faction':t.province?place(t.province):t.partner?g.politics.people[t.person]?.name+' & '+g.politics.people[t.partner]?.name:t.person?g.politics.people[t.person]?.name:t.other?g.factions[t.other]?.name:t.army?'Field army at '+place(g.armies[t.army]?.province):'';
 const effect=e=>Object.entries(e).map(([k,v])=>k==='wedding'?'Creates a dynastic marriage':esc(k.replace(/([A-Z])/g,' $1'))+' '+(v>0?'+':'')+v).join(' · ');
 const btn=(type,id,label)=>'<button class="rowbtn" data-action="expanded" data-type="'+esc(type)+'" data-id="'+esc(id)+'">'+esc(label)+'</button>';
 let html=section('CAMPAIGN EVENTS'),events=currentExpandedEvents(g,r);
 if(events.length){for(const x of events){html+='<div class="rule"><h3>'+esc(x.title)+'</h3><div class="smallnote">'+esc(x.category)+' · '+esc(target(x.target)||'Realm')+' · '+Math.max(0,x.expires-g.turn)+' months remaining</div><p class="paragraph">'+esc(x.description)+'</p>';if(g.turn<(x.availableAt??x.started))html+='<p class="smallnote">Follow-up available in '+(x.availableAt-g.turn)+' months.</p>';else for(const [i,c] of x.choices.entries())html+=btn('resolve-event',x.id+':'+i,c.label+(c.cost?' ('+c.cost+'g)':''))+'<div class="smallnote">'+(effect(c.effects)||'No direct effect')+(c.next?' · Situation continues':'')+'</div>';html+='</div>';}}else html+='<p class="paragraph">No new campaign event.</p>';
 html+='<details class="rule"><summary>Additional decisions</summary>';const ds=expandedDecisions(g,world,r);
 for(const category of [...new Set(ds.map(d=>d.category))]){html+='<div class="sectiontitle">'+esc(category)+'</div>';for(const d of ds.filter(x=>x.category===category))html+='<div class="rule"><b>'+esc(d.title)+'</b><p class="paragraph">'+esc(d.description)+' '+esc(target(d.target)||'')+'</p><div class="smallnote">'+effect(d.effects)+'</div>'+(d.remaining?'<div class="smallnote">Available in '+d.remaining+' months</div>':btn('decision',d.id,'Enact ('+d.cost+'g)'))+'</div>';}
 html+='</details><details class="rule"><summary>Recent campaign choices</summary>'+g.expanded.history.filter(h=>h.realm===r).slice(0,12).map(h=>'<div class="smallnote">'+esc(h.label)+'</div>').join('')+'</details>';return html;
}

export function renderCharacter(g,world,id,esc){const x=characterContext(g,id);if(!x)return '<p>Character no longer available.</p>';const p=x.person,s=g.politics.realms[g.player],f=g.factions[g.player],btn=(action,type,id,label,extra='',input='')=>contextualButton(action,type,id,label,esc,extra,input),link=id=>characterLink(g.politics.people[id],esc),place=id=>provinceLink(id,world,esc);
 let h='<button class="rowbtn" data-character-back>‹ Back to previous screen</button>'+renderPinButton(g,'character',p.id,esc)+'<div class="character-hero">'+portrait(p,esc)+'<span class="eyebrow">'+esc(g.factions[p.realm]?.name||p.realm)+'</span><h2>'+esc(p.name)+'</h2><p>'+esc(p.house)+' · '+p.age+' years · '+(p.alive?(x.prisoner?'Imprisoned':'Living'):'Deceased')+(x.sovereign?' · Sovereign':'')+'</p><p>'+esc((p.traits||[]).join(' · '))+'</p></div><div class="character-skills">'+Object.entries(p.skills||{}).map(([skill,value])=>'<div><small>'+esc(skill)+'</small><b>'+value+'/5</b></div>').join('')+'</div>';
 h+=section('PERSONAL RESOURCES')+'<div class="statlist">'+stat('Personal wealth',fmt(p.wealth||0)+'g')+stat('Influence',characterInfluence(g,p.id)+'/100')+stat('Ambition',esc(characterAgenda(g,p.id)||'Not yet established'))+'</div>';if(x.own&&x.canServe&&p.id!==s.ruler&&g.politics.people[s.ruler].age>=18)h+='<div class="rule">'+btn('politics','personal-gift',p.id,'Personal gift (40 personal gold)')+btn('politics','personal-patronage',p.id,'Sponsor patronage (120 treasury gold)')+btn('politics','personal-rebuke',p.id,'Public rebuke (5 influence)')+'<p class="smallnote">Personal actions have a shared yearly cooldown and affect political relationships.</p></div>';
 if(p.id!==s.ruler)h+='<p class="paragraph">Opinion of your ruler: '+personalOpinion(g,s.ruler,p.id)+'</p>';
 h+=section('FAMILY')+(x.family.length?x.family.map(y=>'<div class="rule"><small>'+esc(y.relation)+'</small> '+link(y.id)+'</div>').join(''):'<p class="paragraph">No recorded close relatives.</p>');
 const seniorTitles=x.titles.filter(t=>t.tier!=='province');
 if(seniorTitles.length){
  h+=section('TITLES')+seniorTitles.map(t=>'<div class="rule"><b>'+esc(t.name)+'</b><div class="smallnote">'+(t.tier==='crown'?'Crown title':'Regional title')+'</div></div>').join('');
 }
 h+=section('LAND AND DUTIES')+(x.council.length||x.offices.length?'<p class="paragraph">'+esc([...x.council,...x.offices].join(' · '))+'</p>':'<p class="paragraph">No appointed court office.</p>');
 for(const a of x.armies)h+='<div class="rule">Commands '+fmt(a.troops)+' troops at '+place(a.province)+'</div>';
 for(const a of x.holdings){
  const title=g.feudal?.titles['c:'+a.id],historic=title?.deJureRealm;
  const historicalNote=historic&&historic!==a.realm
   ?' · 1450 campaign jurisdiction: '+esc(g.factions[historic]?.name||historic)
   :'';
  h+='<div class="rule">'+place(a.id)+'<div class="smallnote">Loyalty '+fmt(a.loyalty)+'% · Wealth '+fmt(a.wealth)+'g'+historicalNote+'</div>'+(x.own&&a.lord!==s.ruler&&p.alive?btn('politics','gift',a.id,'Send gift (100g)')+(a.loyalty<45?btn('politics','concede',a.id,'Concede autonomy (150g)'):''):'')+'</div>';
 }
 if(!x.own){h+=section('FOREIGN RELATIONS')+'<button class="rowbtn" data-action="show-diplomacy" data-target="'+esc(p.realm)+'">Open diplomacy with '+esc(g.factions[p.realm]?.name||p.realm)+'</button>';return h;}
 if(!x.canServe)return h;
 h+=section('AVAILABLE ACTIONS');
 if(!p.spouse){const opts=marriageCandidates(g,g.player).filter(m=>m.a===p.id),field='profile-spouse';h+='<details class="rule" open><summary>Arrange marriage</summary>'+(opts.length?'<select class="select" id="'+field+'">'+opts.map(m=>'<option value="'+esc(m.b)+'">'+esc(m.label)+(m.realm!==g.player?' · '+(marriageTerms(g,p,g.politics.people[m.b]).accepted?'willing':'not willing'):'')+'</option>').join('')+'</select>'+btn('politics','marry',id,'Celebrate wedding (180g)','',field):'<p class="paragraph">No eligible royal match.</p>')+'</details>';}
 const armies=Object.values(g.armies).filter(a=>a.owner===g.player&&!embarked(g,a.id)&&commanderCandidates(g,a.id).some(c=>c.id===id));if(armies.length){const field='profile-army';h+='<details class="rule" open><summary>Military command</summary><select class="select" id="'+field+'">'+armies.map(a=>'<option value="'+esc(a.id)+'">'+fmt(a.infantry+a.archers+a.cavalry)+' troops · '+esc(world.provinces.find(q=>q.id===a.province)?.name||a.province)+'</option>').join('')+'</select><button class="rowbtn" data-action="profile-command" data-id="'+esc(id)+'" data-input="'+field+'">Appoint as commander</button></details>';}
 const eligibleCouncil=p.id!==s.ruler&&!Object.values(s.council).includes(id)&&!Object.values(g.royalCourt?.realms?.[g.player]?.offices||{}).some(o=>o.person===id);
 if(eligibleCouncil)h+='<details class="rule"><summary>Appoint to council</summary>'+Object.entries(s.council).map(([role,person])=>'<p class="smallnote">'+esc(role)+' · Current: '+link(person)+'</p>'+btn('politics','appoint',role,'Appoint '+p.name+' (80g)',id)).join('')+'</details>';
 const offices=Object.entries(COURT_OFFICES).filter(([role])=>!g.royalCourt?.realms?.[g.player]?.offices?.[role]&&courtCandidates(g,g.player,role).some(c=>c.id===id));if(offices.length)h+='<details class="rule"><summary>Household offices</summary>'+offices.map(([role,d])=>'<p class="smallnote">'+esc(d.description)+' · '+d.salary+'g per quarter</p>'+btn('politics','court-appoint',role,d.name+' ('+(d.salary+40)+'g)',id)).join('')+'</details>';
 const titles=titleList(g,g.player).filter(t=>t.tier==='province'&&t.holder===s.ruler&&controller(g,t.province)===g.player&&id!==s.ruler);if(titles.length)h+='<details class="rule"><summary>Grant a crown holding</summary><select class="select" id="profile-title">'+titles.map(t=>'<option value="'+esc(t.id)+'">'+esc(world.provinces.find(q=>q.id===t.province)?.name||t.province)+'</option>').join('')+'</select><button class="rowbtn" data-action="profile-grant" data-id="'+esc(id)+'" data-input="profile-title">Grant selected holding</button></details>';
 return h;}
export function renderProvinceLord(g,world,id,esc){const h=g.politics?.holdings?.[id],p=g.politics?.people?.[h?.lord];if(!h||!p)return '<p class="smallnote">No recorded local lord.</p>';const own=h.realm===g.player&&g.provinces[id]?.owner===g.player&&controller(g,id)===g.player,sovereign=g.politics.realms[h.realm]?.ruler===p.id,btn=(type,label,extra='')=>contextualButton('politics',type,id,label,esc,extra);let out='<div class="rule"><b>'+ (sovereign?'Crown holding':'Local lord')+'</b><p>'+characterLink(p,esc)+'</p><div class="smallnote">Loyalty '+fmt(h.loyalty)+'% · Wealth '+fmt(h.wealth)+'g</div>';if(own&&!sovereign){for(const key of ['tax','levy','autonomy'])out+='<div class="smallnote">'+esc(key)+': '+['Low','Standard','High'][h[key]]+'</div><div class="contract-options">'+[0,1,2].filter(n=>n!==h[key]).map(n=>btn(key,['Low','Standard','High'][n],n)).join('')+'</div>';out+=btn('gift','Send gift (100g)')+(h.loyalty<45?btn('concede','Negotiate concession (150g)'):'');}return out+'</div>';}
export function renderCampaignHub(g,esc){const x=campaignLinks(g),r=g.politics?.people?.[x.ruler];return '<div class="rule campaign-hub"><h3>Your kingdom</h3><p>Sovereign: '+characterLink(r,esc)+'</p><div class="hub-links">'+sectionLink('dynasty','Dynasty & inheritance',esc)+sectionLink('council','Royal council',esc)+sectionLink('characters','Character finder',esc)+sectionLink('vassals',x.vassals+' vassals · '+x.disloyal+' disloyal holdings',esc)+sectionLink('military',x.armies+' armies · '+fmt(x.troops)+' troops',esc)+sectionLink('diplomacy','Foreign relations',esc)+sectionLink('political',realmWarContext(g).length+' active wars · Politics',esc,'WARS AND PEACE')+sectionLink('economy','Treasury & production',esc)+sectionLink('stories','Events & decisions',esc)+sectionLink('society','Culture & government',esc)+sectionLink('naval','Fleets & overseas travel',esc)+'</div></div>';}

export function renderProvinceConnections(g,world,id,esc){const p=g.provinces[id],local=g.economy?.provinces?.[id];if(!p)return '';const owner=p.owner,our=owner===g.player&&controller(g,id)===g.player,btn=(type,label)=>contextualButton('conflict',type,id,label,esc);let out='';
 const title=g.feudal?.titles['c:'+id],district=g.feudal?.titles[title?.parent],historic=title?.deJureRealm;
 if(district){
  out+='<div class="rule"><b>'+esc(district.name)+'</b><div class="statlist">'+stat('Current realm',esc(g.factions[owner]?.name||owner))+(historic&&historic!==owner?stat('1450 campaign jurisdiction',esc(g.factions[historic]?.name||historic)):'')+'</div></div>';
 }
 if(local)out+='<div class="rule"><b>Local economy</b><div class="statlist">'+stat('Grain reserve',fmt(local.stock?.grain||0))+stat('Timber reserve',fmt(local.stock?.timber||0))+stat('Tools reserve',fmt(local.stock?.tools||0))+stat('Shortage',fmt(local.shortage||0))+'</div>'+(our?sectionLink('economy','Manage production and trade',esc):'')+'</div>';
 if(our){out+=sectionLink('titles','Manage land titles',esc)+sectionLink('military','Manage field armies',esc);if(g.naval?.ports?.[id])out+=sectionLink('naval','Manage port and fleet',esc);}
 else if(owner!==g.player&&g.politics?.realms?.[owner]){const claim=availableClaims(g,g.player).find(c=>c.province===id),wars=realmWarContext(g,owner),scheme=Object.values(g.conflict?.schemes||{}).find(s=>s.realm===g.player&&s.target===id&&s.kind==='fabricate'&&s.status==='active');out+='<div class="rule"><b>Claims and war</b>'+(wars.length?'<p class="paragraph">Active war · Score '+wars[0].ourScore+'</p>'+sectionLink('political','War and peace terms',esc,'WARS AND PEACE'):claim?btn('declare','Declare claim war (5 prestige)'):scheme?'<p class="smallnote">Claim in preparation · '+Math.max(0,scheme.due-g.turn)+' months remaining.</p>':contextualButton('conflict','scheme','fabricate','Fabricate claim (110g)',esc,id))+'</div>';}
 return out;}

const portrait=(p,esc)=>{const a=portraitMark(p);return '<span class="portrait-mark" style="background:'+a.color+'">'+esc(a.initials)+'</span>';};
const charCard=(p,esc,detail='')=>'<div class="person-row">'+portrait(p,esc)+'<div>'+characterLink(p,esc)+'<small>'+esc(detail||p.house||'')+'</small></div></div>';
export function renderCharacterDirectory(g,esc,state){const rows=characterDirectory(g,state),skills=['martial','diplomacy','stewardship','intrigue','learning'];return section('CHARACTER FINDER')+'<div class="directory-controls"><input id="people-query" type="search" placeholder="Search people, houses or traits" aria-label="Search characters" value="'+esc(state.query)+'"><select id="people-scope" class="select" aria-label="Character scope">'+[['court','Your realm'],['family','Your dynasty'],['foreign','Foreign characters'],['all','All characters']].map(([id,n])=>'<option value="'+id+'" '+(state.scope===id?'selected':'')+'>'+n+'</option>').join('')+'</select><select id="people-sort" class="select" aria-label="Sort characters">'+['name','age',...skills].map(id=>'<option value="'+id+'" '+(state.sort===id?'selected':'')+'>'+id.charAt(0).toUpperCase()+id.slice(1)+'</option>').join('')+'</select></div><p class="smallnote">'+rows.length+' matching characters'+(rows.length>80?' · first 80 shown; narrow search':'')+'</p><div class="directory-list">'+rows.slice(0,80).map(p=>charCard(p,esc,p.age+'y · '+(g.factions[p.realm]?.name||p.realm)+' · Martial '+p.skills.martial+' · Diplomacy '+p.skills.diplomacy)).join('')+'</div>';}
export function renderDynasty(g,esc){const p=g.politics,s=p.realms[g.player],r=p.people[s.ruler],heir=successionPreview(g,g.player),node=id=>p.people[id]?charCard(p.people[id],esc,p.people[id].age+'y · '+(p.people[id].alive?'Living':'Deceased')+(heir?.id===id?' · HEIR':'')):'',row=(label,ids)=>'<div class="family-generation"><small>'+label+'</small>'+ids.map(node).join('')+'</div>';const line=successionCandidates(g,g.player),election=s.law==='elective'?electionView(g,g.player):null,ballot=election?section('CROWN ELECTION')+'<div class="rule"><p class="paragraph">Landed electors and councillors vote independently. Your nomination influences your own vote and supporters.</p>'+election.candidates.slice(0,20).map(x=>'<div class="rule">'+characterLink(p.people[x.id],esc)+' · '+x.votes+' votes'+(x.id===election.nominee?' · Nominated':'')+(x.id===election.winner?' · Leading':'')+contextualButton('politics','nominate-successor',x.id,'Nominate',esc)+'</div>').join('')+'<details><summary>Elector votes ('+election.electors.length+')</summary>'+election.electors.map(x=>'<p class="smallnote">'+characterLink(p.people[x.id],esc)+' → '+characterLink(p.people[x.vote],esc)+' · Weight '+x.weight+'</p>').join('')+'</details></div>':section('LINE OF SUCCESSION')+'<div class="rule">'+(line.length?line.slice(0,12).map((x,i)=>'<p class="smallnote">'+(i+1)+'. '+characterLink(x,esc)+'</p>').join(''):'<p class="paragraph">No eligible dynastic successor.</p>')+'</div>';return section('DYNASTY AND SUCCESSION')+'<div class="rule"><h3>'+esc(r.house)+'</h3><p class="paragraph">Succession: '+esc(s.law)+' · Expected heir: '+characterLink(heir,esc)+'</p></div>'+renderRegency(g,esc)+ballot+row('Parents',r.parents||[])+row('Sovereign and consort',[r.id,r.spouse].filter(Boolean))+row('Children',r.children||[])+row('Grandchildren',(r.children||[]).flatMap(id=>p.people[id]?.children||[]))+sectionLink('court','Marriage arrangements and succession laws',esc,'SUCCESSION LAW');}
export function renderCouncilDirectory(g,esc,world){const p=g.politics,s=p.realms[g.player],r=p.people[s.ruler],f=g.factions[g.player],skills={chancellor:'diplomacy',marshal:'martial',steward:'stewardship',spymaster:'intrigue',scholar:'learning'},duties={chancellor:'Foreign relations and political negotiations',marshal:'Military training and levies',steward:'Tax efficiency and administration',spymaster:'Intelligence and schemes',scholar:'Scholarship and community reconciliation'},busy=new Set([...Object.values(s.council),...Object.values(g.royalCourt?.realms?.[g.player]?.offices||{}).map(o=>o.person)]);return section('ROYAL COUNCIL')+Object.entries(s.council).map(([role,id])=>{const skill=skills[role]||'learning',field='council-candidate-'+role,opts=Object.values(p.people).filter(c=>c.alive&&c.realm===g.player&&c.age>=18&&c.id!==r.id&&!busy.has(c.id)&&!isImprisoned(g,c.id)).sort((a,b)=>b.skills[skill]-a.skills[skill]);return '<div class="rule"><h3>'+esc(role)+'</h3><p class="smallnote">'+esc(duties[role]||'Government duties')+'</p>'+(p.people[id]?charCard(p.people[id],esc,skill+' '+p.people[id].skills[skill]+'/5'):'Vacant')+(opts.length?'<select class="select" id="'+field+'">'+opts.map(c=>'<option value="'+esc(c.id)+'">'+esc(c.name)+' · '+c.skills[skill]+'/5</option>').join('')+'</select>'+contextualButton('politics','appoint',role,'Appoint (80g)',esc,'',field):'<p class="smallnote">No available candidate.</p>')+renderCouncilAssignments(g,world,role,esc)+'</div>';}).join('')+sectionLink('court','Household offices',esc,'ROYAL HOUSEHOLD OFFICES')+sectionLink('political','Council authority and voting',esc,'COUNCIL AUTHORITY');}
export function renderVassalDirectory(g,world,esc,sort){const est=politicalEstates(g,g.player),level=authorityLevel(g,g.player),mod=authorityModifiers(g,g.player,est),hierarchy=feudalHierarchy(g,g.player),obligations=obligationProfile(g,g.player,hierarchy),rows=vassalDirectory(g,sort);if(sort==='power')rows.sort((a,b)=>(est.byLord[b.id]?.power||0)-(est.byLord[a.id]?.power||0));const wait=Math.max(0,(g.authority?.realms?.[g.player]?.changed??-120)+60-g.turn),controls=[level-1,level+1].filter(n=>n>=0&&n<=3).map(n=>contextualButton('politics','authority',String(n),(n>level?'Raise: ':'Lower: ')+AUTHORITY[n].name+(n>level?' (200g)':''),esc)).join('');
const petitions=pendingVassalPetitions(g,g.player),requests=petitions.length?section('VASSAL PETITIONS')+petitions.map(x=>'<div class="rule"><b>'+characterLink(g.politics.people[x.person],esc)+' · '+esc(x.kind==='tax'?'Lower taxation':x.kind==='autonomy'?'More autonomy':'Council seat')+'</b><p class="smallnote">'+provinceLink(x.province,world,esc)+' · '+Math.max(0,x.deadline-g.turn)+' months to respond</p>'+contextualButton('politics','vassal-petition',x.id,'Accept',esc,'accept')+contextualButton('politics','vassal-petition',x.id,'Compromise (75g)',esc,'compromise')+contextualButton('politics','vassal-petition',x.id,'Reject',esc,'reject')+'</div>').join(''):'';
const disputes=estateDisputes(g,g.player),conflicts=disputes.length?section('ESTATE TITLE DISPUTES')+disputes.map(x=>'<div class="rule"><h3>'+esc(x.status==='feud'?'Internal feud':'Disputed claim')+'</h3><p>'+characterLink(g.politics.people[x.claimant],esc)+' challenges '+characterLink(g.politics.people[x.defender],esc)+' for '+provinceLink(x.target,world,esc)+'</p><p class="smallnote">'+Math.max(0,x.deadline-g.turn)+' months remaining · Sovereign borders do not change.</p>'+contextualButton('politics','estate-dispute',x.id,'Mediate (90g)',esc,'mediate')+contextualButton('politics','estate-dispute',x.id,'Recognize claim (-5 legitimacy)',esc,'recognize')+contextualButton('politics','estate-dispute',x.id,'Deny claim',esc,'deny')+'</div>').join(''):'';
return requests+conflicts+section('CROWN AUTHORITY')+'<div class="rule"><h3>'+esc(AUTHORITY[level].name)+'</h3><div class="statlist">'+stat('Direct domain',est.domain+' / '+est.limit)+stat('Tax modifier',fmt(mod.tax*100)+'%')+stat('Levy modifier',fmt(mod.levy*100)+'%')+stat('Vassal loyalty target',String(mod.loyalty))+stat('Direct vassal holdings',obligations.directCount)+stat('Sub-vassal holdings',obligations.subCount)+stat('Crown tax from sub-vassals',Math.round(obligations.indirectShare*100)+'%')+'</div>'+(est.excess?'<p class="smallnote">Above domain limit: grant holdings to reduce administration penalties.</p>':'')+(wait?'<p class="smallnote">Reform available in '+wait+' months.</p>':controls)+'</div>'+section('VASSALS')+'<p class="paragraph">'+rows.length+' landed vassals. Powerful lords expect a council seat; neglect lowers long-term loyalty.</p><select class="select" id="vassal-sort" aria-label="Sort vassals">'+[['loyalty','Lowest loyalty'],['power','Most powerful'],['wealth','Highest wealth'],['holdings','Most holdings'],['population','Largest population']].map(([id,n])=>'<option value="'+id+'" '+(sort===id?'selected':'')+'>'+n+'</option>').join('')+'</select>'+rows.map(x=>{const p=est.byLord[x.id];return '<div class="rule">'+charCard(x.person,esc,Math.round(x.loyalty)+'% loyalty · '+fmt(x.wealth)+'g')+'<div class="smallnote">'+x.holdings.length+' holdings · '+fmt(x.population)+'k population · '+Math.round((p?.share||0)*100)+'% of estate power'+(p?.powerful?' · Powerful vassal':'')+(p?.grievance?' · Wants council seat':p?.onCouncil?' · On council':'')+'</div>'+(p?.grievance?sectionLink('council','Review council appointments',esc):'')+'<p class="smallnote">Agenda: '+esc(vassalCourt(g,x.id)?.agenda||'Maintain estates')+' · Liege: '+characterLink(g.politics.people[hierarchy.byLord[x.id]?.liege],esc)+'</p>'+(hierarchy.byLord[x.id]?.subjects.length?'<p class="smallnote">Subordinate lords: '+hierarchy.byLord[x.id].subjects.map(id=>characterLink(g.politics.people[id],esc)).join(', ')+'</p>':'')+'<details><summary>Holdings and obligations</summary>'+x.holdings.map(id=>'<div class="rule">'+provinceLink(id,world,esc)+renderProvinceLord(g,world,id,esc)+'</div>').join('')+'</details></div>';}).join('')+sectionLink('political','Factions and civil wars',esc,'FACTIONS AND CIVIL WARS');}

function renderCouncilAssignments(g,world,role,esc){const r=g.player,t=g.councilTasks?.realms?.[r]?.[role],defs=COUNCIL_TASKS[role]||{},place=id=>world?.provinces?.find(p=>p.id===id)?.name||id;if(t){const d=defs[t.kind],person=g.politics.people[t.person],skill=Math.max(1,person?.skills?.[d?.skill]||1),pct=Math.min(100,Math.round(t.progress/t.required*100));return '<div class="rule"><b>'+esc(d?.name||t.kind)+'</b><p class="smallnote">'+pct+'% complete · approximately '+Math.ceil((t.required-t.progress)/skill)+' months remaining</p><div class="unithealth"><div style="width:'+pct+'%"></div></div>'+contextualButton('council-task','cancel',role,'Cancel assignment',esc)+'</div>';}return '<details class="rule"><summary>Assign council task</summary>'+Object.entries(defs).map(([id,d])=>{const field='task-'+role+'-'+id,targets=councilTaskTargets(g,r,role,id),label=target=>d.target==='foreign'?g.factions[target]?.name:d.target==='realm'?g.factions[r].name:d.target==='army'?place(g.armies[target].province)+' · '+(g.armies[target].infantry+g.armies[target].archers+g.armies[target].cavalry)+' troops':place(target);return '<div class="rule"><b>'+esc(d.name)+'</b><p class="smallnote">'+d.cost+' gold · '+d.months+' months at skill 3</p>'+(targets.length?'<select class="select" id="'+field+'">'+targets.map(x=>'<option value="'+esc(x)+'">'+esc(label(x)||x)+'</option>').join('')+'</select>'+contextualButton('council-task',id,role,'Begin assignment',esc,'',field):'<p class="smallnote">No eligible target.</p>')+'</div>';}).join('')+'</details>';}

export function renderCampaignSearch(g,world,esc,query=''){const rows=campaignSearch(g,world,query);return section('CAMPAIGN FINDER')+'<label for="campaign-query" class="smallnote">Find a character, province, kingdom or management page</label><input id="campaign-query" class="select" type="search" placeholder="Search the campaign" value="'+esc(query)+'"><div class="finder-results">'+(rows.length?rows.map(x=>'<button class="finder-row" '+(x.kind==='page'?'data-priority-tab':x.kind==='province'?'data-province-link':'data-character')+'="'+esc(x.id)+'"><b>'+esc(x.label)+'</b><small>'+esc(x.detail)+'</small></button>').join(''):'<p class="paragraph">No matching results.</p>')+'</div>';}

export function renderRegency(g,esc){const r=g.player,x=regencyView(g,r);if(!x)return '';const p=g.politics.people,head=p[x.sovereign],opts=regentCandidates(g,r).filter(c=>c.id!==x.regent),wait=Math.max(0,x.lastAction+6-g.turn);return section('REGENCY AND AUTHORITY')+'<div class="rule"><h3>'+characterLink(p[x.regent],esc)+'</h3><p class="paragraph">'+(head.age<18?'Minority regency':'Entrenched regency')+' · Influence '+x.influence+'/100</p><p class="smallnote">'+(x.influence>=65?'The regent can block wars and reforms, depending on loyalty and personality.':'The crown retains effective control of major decisions.')+'</p>'+(wait?'<p class="smallnote">Negotiations available in '+wait+' months.</p>':contextualButton('politics','regency-concession',x.regent,'Negotiate concession (100g)',esc)+(head.age>=18?contextualButton('politics','regency-assert',x.regent,'Assert authority (20 prestige)',esc):'')+(opts.length&&x.influence<65?'<select class="select" id="regent-candidate">'+opts.map(c=>'<option value="'+esc(c.id)+'">'+esc(p[c.id].name)+'</option>').join('')+'</select>'+contextualButton('politics','regency-replace','', 'Replace regent (120g)',esc,'','regent-candidate'):''))+'</div>';}
